/* Task: pointer — binary-tree traversal (the paper's worked
 * example: a binary tree built with malloc'd nodes, traversed
 * recursively). Deliberately HLS-incompatible:
 *  - each node is heap-allocated with malloc/free
 *  - the tree is linked by raw Node * pointers (children, parameters)
 *  - build(), traverse() and free_tree() are all recursive
 * Behaviour: build a complete binary tree from an array, inorder
 * traverse it into out[], print a position-weighted checksum.
 * Test inputs are generated by the harness (n, seed) sweep, not baked in.
 */
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int val;
    struct Node *left;
    struct Node *right;
} Node;

int trav_idx = 0;

Node *new_node(int v) {
    Node *n = (Node *)malloc(sizeof(Node));
    n->val = v;
    n->left = NULL;
    n->right = NULL;
    return n;
}

Node *build(int *vals, int n, int i) {
    if (i >= n) {
        return NULL;
    }
    Node *root = new_node(vals[i]);
    root->left = build(vals, n, 2 * i + 1);
    root->right = build(vals, n, 2 * i + 2);
    return root;
}

void traverse(Node *root, int *out) {
    if (!root) {
        return;
    }
    traverse(root->left, out);
    out[trav_idx++] = root->val;
    traverse(root->right, out);
}

void free_tree(Node *root) {
    if (!root) {
        return;
    }
    free_tree(root->left);
    free_tree(root->right);
    free(root);
}

static unsigned int rng_state = 1;
static int next_rand_int(void) {
    rng_state = rng_state * 1103515245u + 12345u;
    return (int)((rng_state >> 16) & 0xFF);
}

int main(int argc, char **argv) {
    int n = 64;
    if (argc > 1) {
        n = atoi(argv[1]);
    }
    if (argc > 2) {
        rng_state = (unsigned int)atoi(argv[2]);
    }
    int *vals = (int *)malloc(n * sizeof(int));
    int *out = (int *)malloc(n * sizeof(int));
    int i;
    for (i = 0; i < n; i++) {
        vals[i] = next_rand_int();
    }
    Node *root = build(vals, n, 0);
    trav_idx = 0;
    traverse(root, out);
    double checksum = 0.0;
    for (i = 0; i < n; i++) {
        checksum += (double)out[i] * (i + 1);
    }
    printf("checksum=%.6f\n", checksum);
    free_tree(root);
    free(vals);
    free(out);
    return 0;
}
